Lemma mirror_ok_0RB1RD_1RC0LD_1LA1RB_0RB1LD : mirror_tm tm_0RB1RD_1RC0LD_1LA1RB_0RB1LD = tmm_0RB1RD_1RC0LD_1LA1RB_0RB1LD.
Proof.
  apply functional_extensionality; intro q;
    apply functional_extensionality; intro b; destruct q, b; reflexivity.
Qed.

Definition Cc_0RB1RD_1RC0LD_1LA1RB_0RB1LD (p : positive) : cconf := (StB, (Jp p ++ [S0], S0, [])).
