Definition tm_1RB0LB_0RC0LA_1RD____1LA1RC : TM := fun q s => match q, s with
  | StA, S0 => mk S1 DR StB | StA, S1 => mk S0 DL StB
  | StB, S0 => mk S0 DR StC | StB, S1 => mk S0 DL StA
