  unfold Cc_1RB0LB_0RC0LA_1RD____1LA1RC, cden, A1_1RB0LB_0RC0LA_1RD____1LA1RC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  rewrite H2. first [ rewrite <- (app_assoc (rep [S0;S0] j)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapi_1RB0LB_0RC0LA_1RD____1LA1RC : forall p j q0, cview p = (j, Some q0) ->
  exists n, 0 < n /\ csteps tm n (Cc p) = Some (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. exists (4 * j + 4). split; [lia|].
  rewrite (gsi_1RB0LB_0RC0LA_1RD____1LA1RC p j q0 E).
  rewrite (srun_sound tm false true chi_1RB0LB_0RC0LA_1RD____1LA1RC A0_1RB0LB_0RC0LA_1RD____1LA1RC A1_1RB0LB_0RC0LA_1RD____1LA1RC 4 4
             run_int_1RB0LB_0RC0LA_1RD____1LA1RC (Bp q0 ++ [S0]) [] j
             ltac:(discriminate) ltac:(reflexivity)).
  f_equal. exact (gei_1RB0LB_0RC0LA_1RD____1LA1RC p j q0 E).
Qed.

Lemma gso_1RB0LB_0RC0LA_1RD____1LA1RC : forall p j, cview p = (S j, None) ->
  Cc p = cden [] [] j B0_1RB0LB_0RC0LA_1RD____1LA1RC.
Proof.
  intros p j E. destruct (BpCounter.cview_none_B p j E) as (H1 & _).
  unfold Cc_1RB0LB_0RC0LA_1RD____1LA1RC, cden, B0_1RB0LB_0RC0LA_1RD____1LA1RC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with (j) by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lbl_1RB0LB_0RC0LA_1RD____1LA1RC : forall q l h r, lift (q,(l ++ [S0],h,r)) = lift (q,(l,h,r)).
Proof. intros. unfold lift; simpl. rewrite lift_side_app_blank. reflexivity. Qed.

Lemma geo_1RB0LB_0RC0LA_1RD____1LA1RC : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB0LB_0RC0LA_1RD____1LA1RC) = lift (Cc (Pos.succ p)).
Proof.
  intros p j E. destruct (BpCounter.cview_none_B p j E) as (_ & H2).
  assert (HD : cden [] [] j B1_1RB0LB_0RC0LA_1RD____1LA1RC
             = (StB, (rep [S0;S0] (S j) ++ [S0;S1], S0, [S1]))).
  { unfold cden, B1_1RB0LB_0RC0LA_1RD____1LA1RC, sden, sflat;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 1) with (S j) by lia.
    replace (0 * j + 0) with 0 by lia.
    cbn [rep app]. first [ reflexivity
      | rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  assert (HC : Cc (Pos.succ p) = (StB, ((rep [S0;S0] (S j) ++ [S0;S1]) ++ [S0], S0, [S1]))).
  { unfold Cc_1RB0LB_0RC0LA_1RD____1LA1RC. rewrite H2.
    first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite !lbl_1RB0LB_0RC0LA_1RD____1LA1RC. reflexivity.
Qed.

(** ** The lap *)

Lemma lap_1RB0LB_0RC0LA_1RD____1LA1RC : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_1RB0LB_0RC0LA_1RD____1LA1RC p j q0 E) as (n & Hn & Hrun).
    exists n, (Cc (Pos.succ p)).
    split; [exact Hrun | split; [reflexivity | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB0LB_0RC0LA_1RD____1LA1RC B0_1RB0LB_0RC0LA_1RD____1LA1RC B1_1RB0LB_0RC0LA_1RD____1LA1RC 4 8 p j' [] []).
    + exact run_ovf_1RB0LB_0RC0LA_1RD____1LA1RC.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB0LB_0RC0LA_1RD____1LA1RC p j' E).
    + exact (geo_1RB0LB_0RC0LA_1RD____1LA1RC p j' E).
    + lia.
Qed.

(** ** Bootstrap *)

Lemma bootq_1RB0LB_0RC0LA_1RD____1LA1RC : stepn tmm_1RB0LB_0RC0LA_1RD____1LA1RC 5 InitES = Some (lift (Cc 1)).
Proof.
  assert (H : match csteps tmm_1RB0LB_0RC0LA_1RD____1LA1RC 5 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tmm_1RB0LB_0RC0LA_1RD____1LA1RC 5 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** the quasihalt witness: a pinned instruction fired in the prefix *)
Lemma wit_1RB0LB_0RC0LA_1RD____1LA1RC : existsb (fun tg => cfires tmm_1RB0LB_0RC0LA_1RD____1LA1RC c0 5 tg) pins_1RB0LB_0RC0LA_1RD____1LA1RC = true.
Proof. vm_compute. reflexivity. Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_1RB0LB_0RC0LA_1RD____1LA1RC : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB0LB_0RC0LA_1RD____1LA1RC = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_1RB0LB_0RC0LA_1RD____1LA1RC p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_1RB0LB_0RC0LA_1RD____1LA1RC p j E)].
Qed.


(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_1RB0LB_0RC0LA_1RD____1LA1RC : forall t, ~ In t pins_1RB0LB_0RC0LA_1RD____1LA1RC ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n, 0 < n /\ csteps tm n (Cc p0) = Some (Cc (Pos.succ p0)))
    by exact lapi_1RB0LB_0RC0LA_1RD____1LA1RC.
  destruct t as [q b]; destruct q, b.
  - (* A0: pinned *)
    exfalso. apply Hnp. apply tr_inb_spec. reflexivity.
  - (* A1 *)
    apply (fire_via_ovf tm Cc Hi (StA, S1)), fireo_1RB0LB_0RC0LA_1RD____1LA1RC
      with (l := [SWin 2; SCycL 2 0; SWin 1; SWinL 2]).
    vm_compute; reflexivity.
  - (* B0 *)
    apply (fire_via_ovf tm Cc Hi (StB, S0)), fireo_1RB0LB_0RC0LA_1RD____1LA1RC
      with (l := []).
    vm_compute; reflexivity.
  - (* B1 *)
    apply (fire_via_ovf tm Cc Hi (StB, S1)), fireo_1RB0LB_0RC0LA_1RD____1LA1RC
      with (l := [SWin 2; SCycL 2 0; SWin 1; SWinL 3]).
    vm_compute; reflexivity.
  - (* C0 *)
    apply (fire_via_ovf tm Cc Hi (StC, S0)), fireo_1RB0LB_0RC0LA_1RD____1LA1RC
      with (l := [SWin 1]).
    vm_compute; reflexivity.
  - (* C1: pinned *)
    exfalso. apply Hnp. apply tr_inb_spec. reflexivity.
  - (* D0 *)
    apply (fire_via_ovf tm Cc Hi (StD, S0)), fireo_1RB0LB_0RC0LA_1RD____1LA1RC
      with (l := [SWin 2; SCycL 2 0; SWin 1; SWinL 1]).
    vm_compute; reflexivity.
  - (* D1 *)
    apply (fire_via_ovf tm Cc Hi (StD, S1)), fireo_1RB0LB_0RC0LA_1RD____1LA1RC
      with (l := [SWin 2]).
    vm_compute; reflexivity.
Qed.

Theorem qhtrm_1RB0LB_0RC0LA_1RD____1LA1RC : NonHalt tmm_1RB0LB_0RC0LA_1RD____1LA1RC /\ QHBoundTr 32779478 tmm_1RB0LB_0RC0LA_1RD____1LA1RC /\ QuasiHaltsTr tmm_1RB0LB_0RC0LA_1RD____1LA1RC.
Proof.
  apply (lap_qh_stage tmm_1RB0LB_0RC0LA_1RD____1LA1RC pins_1RB0LB_0RC0LA_1RD____1LA1RC Cc 1 5 32779478).
  - exact bootq_1RB0LB_0RC0LA_1RD____1LA1RC.
  - intros p _. apply lap_1RB0LB_0RC0LA_1RD____1LA1RC.
  - intros t Ht p _. apply fire_1RB0LB_0RC0LA_1RD____1LA1RC. exact Ht.
  - exact wit_1RB0LB_0RC0LA_1RD____1LA1RC.
  - apply qcleb_QC_09. reflexivity.
Qed.

Theorem qhtr_1RB0LB_0RC0LA_1RD____1LA1RC : NonHalt tm_1RB0LB_0RC0LA_1RD____1LA1RC /\ QHBoundTr 32779478 tm_1RB0LB_0RC0LA_1RD____1LA1RC /\ QuasiHaltsTr tm_1RB0LB_0RC0LA_1RD____1LA1RC.
Proof. apply (qh_triple_unmirror 32779478 tm_1RB0LB_0RC0LA_1RD____1LA1RC). rewrite mirror_ok_1RB0LB_0RC0LA_1RD____1LA1RC. exact qhtrm_1RB0LB_0RC0LA_1RD____1LA1RC. Qed.

End B_QC_09_018.

