Lemma geo_1RB0LB_1LA1RC_1LD0RC_0LD1RB : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB0LB_1LA1RC_1LD0RC_0LD1RB) = lift (Cc (Pos.succ p)).
