  assert (HD : cden [] [] j B1_1RB0LB_1LA1RC_1LD0RC_0LD1RB
             = (StD, (rep [S0] (S j) ++ [S1], S0, [S1;S1;S1]))).
  { unfold cden, B1_1RB0LB_1LA1RC_1LD0RC_0LD1RB, sden, sflat;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 1) with (S j) by lia.
    replace (0 * j + 0) with 0 by lia.
