    apply (lap_of_run tm Cc true true cho_1RB0LB_1LA1RC_1LD0RC_0LD1RB B0_1RB0LB_1LA1RC_1LD0RC_0LD1RB B1_1RB0LB_1LA1RC_1LD0RC_0LD1RB 2 12 p j' [] []).
