      with (l := [SWin 2; SRotL 1; SWin 1; SCycL 2 0; SWin 1; SWinL 3]).
    vm_compute; reflexivity.
  - (* B0 *)
    apply (fire_via_ovf tm Cc Hi (StB, S0)), fireo_1RB0LB_1LC0LA_1LB1RD_1RC0RC
      with (l := []).
    vm_compute; reflexivity.
  - (* B1 *)
