      with (l := [SWin 2; SRotL 1; SWin 1; SCycL 2 0; SWin 1; SWinL 1]).
    vm_compute; reflexivity.
  - (* C1 *)
    apply (fire_via_ovf tm Cc Hi (StC, S1)), fireo_1RB0LB_1LC0LA_1LB1RD_1RC0RC
      with (l := [SWin 1]).
    vm_compute; reflexivity.
  - (* D0 *)
    apply (fire_via_ovf tm Cc Hi (StD, S0)), fireo_1RB0LB_1LC0LA_1LB1RD_1RC0RC
      with (l := [SWin 2; SRotL 1; SWin 1; SCycL 2 0; SWin 1]).
