(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gz_1RB0LB_1LC1RD_1LA0LC_0RD1LC : forall p q0, cview p = (0, Some q0) ->
  Cc p = cden (Dp q0 ++ [S0]) [] 0 Z0_1RB0LB_1LC1RD_1LA0LC_0RD1LC /\
  cden (Dp q0 ++ [S0]) [] 0 Z1_1RB0LB_1LC1RD_1LA0LC_0RD1LC = Cc (Pos.succ p).
Proof.
  intros p q0 E. destruct (DpCounter.cview_some_D p 0 q0 E) as (H1 & H2).
  unfold Cc_1RB0LB_1LC1RD_1LA0LC_0RD1LC, cden, Z0_1RB0LB_1LC1RD_1LA0LC_0RD1LC, Z1_1RB0LB_1LC1RD_1LA0LC_0RD1LC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  split.
  - rewrite H1; cbn [rep app]. first [ rewrite <- app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
  - rewrite H2; cbn [rep app]. first [ rewrite <- app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma gp_1RB0LB_1LC1RD_1LA0LC_0RD1LC : forall p j q0, cview p = (S j, Some q0) ->
  Cc p = cden (Dp q0 ++ [S0]) [] j P0_1RB0LB_1LC1RD_1LA0LC_0RD1LC /\
  cden (Dp q0 ++ [S0]) [] j P1_1RB0LB_1LC1RD_1LA0LC_0RD1LC = Cc (Pos.succ p).
Proof.
  intros p j q0 E. destruct (DpCounter.cview_some_D p (S j) q0 E) as (H1 & H2).
  unfold Cc_1RB0LB_1LC1RD_1LA0LC_0RD1LC, cden, P0_1RB0LB_1LC1RD_1LA0LC_0RD1LC, P1_1RB0LB_1LC1RD_1LA0LC_0RD1LC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  split.
  - rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
  - rewrite H2; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapi_1RB0LB_1LC1RD_1LA0LC_0RD1LC : forall p j q0, cview p = (j, Some q0) ->
  exists n, 0 < n /\ csteps tm n (Cc p) = Some (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. destruct j as [|j'].
  - destruct (gz_1RB0LB_1LC1RD_1LA0LC_0RD1LC p q0 E) as (HA & HB).
    exists (0 * 0 + 4). split; [lia|].
    rewrite HA.
    rewrite (srun_sound tm false true chz_1RB0LB_1LC1RD_1LA0LC_0RD1LC Z0_1RB0LB_1LC1RD_1LA0LC_0RD1LC Z1_1RB0LB_1LC1RD_1LA0LC_0RD1LC 0 4
               run_z_1RB0LB_1LC1RD_1LA0LC_0RD1LC (Dp q0 ++ [S0]) [] 0
               ltac:(discriminate) ltac:(reflexivity)).
    f_equal. exact HB.
  - destruct (gp_1RB0LB_1LC1RD_1LA0LC_0RD1LC p j' q0 E) as (HA & HB).
    exists (4 * j' + 8). split; [lia|].
    rewrite HA.
    rewrite (srun_sound tm false true chp_1RB0LB_1LC1RD_1LA0LC_0RD1LC P0_1RB0LB_1LC1RD_1LA0LC_0RD1LC P1_1RB0LB_1LC1RD_1LA0LC_0RD1LC 4 8
               run_p_1RB0LB_1LC1RD_1LA0LC_0RD1LC (Dp q0 ++ [S0]) [] j'
               ltac:(discriminate) ltac:(reflexivity)).
    f_equal. exact HB.
Qed.

Lemma gso_1RB0LB_1LC1RD_1LA0LC_0RD1LC : forall p j, cview p = (S j, None) ->
  Cc p = cden [] [] j B0_1RB0LB_1LC1RD_1LA0LC_0RD1LC.
