(** ** The lap *)

Lemma lap_1RB0LB_1LC1RD_1LA0LC_0RD1LC : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
