    apply (lap_of_run tm Cc true true cho_1RB0LB_1LC1RD_1LA0LC_0RD1LC B0_1RB0LB_1LC1RD_1LA0LC_0RD1LC B1_1RB0LB_1LC1RD_1LA0LC_0RD1LC 4 8 p j' [] []).
    + exact run_ovf_1RB0LB_1LC1RD_1LA0LC_0RD1LC.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB0LB_1LC1RD_1LA0LC_0RD1LC p j' E).
    + exact (geo_1RB0LB_1LC1RD_1LA0LC_0RD1LC p j' E).
